class Solution {
public:
    long long minCost(string s, string t, int flipCost, int swapCost, int crossCost) {
        long long a = 0, b = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '1' && t[i] == '0') a++;
            else if (s[i] == '0' && t[i] == '1') b++;
        }
        long long m = min(a, b), r = llabs(a - b);
        long long f = flipCost;
        return m * min((long long)swapCost, 2 * f) + r * f;
    }
};

